import sys

CHARS = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"


def increment_id(id_str: str) -> str:
    """Increment a base-36 id string by 1, preserving leading zeros if any."""
    chars = list(id_str)
    for i in range(len(chars) - 1, -1, -1):
        idx = CHARS.index(chars[i])
        if idx < 35:
            chars[i] = CHARS[idx + 1]
            return "".join(chars)
        chars[i] = CHARS[0]
    # Overflow: all digits wrapped, prepend '1'
    return "1" + "".join(chars)


def main():
    with open("ids.txt") as f:
        lines = [line.strip() for line in f if line.strip()]

    if not lines:
        print("ORD-0000")
        return

    last_id = lines[-1]
    prefix = last_id[:4]  # "ORD-"
    suffix = last_id[4:]  # e.g. "243G"
    next_suffix = increment_id(suffix)
    print(f"{prefix}{next_suffix}")


if __name__ == "__main__":
    main()

