import sys
import os

BASE36 = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"

def increment(s: str) -> str:
    """Increment a base-36 string by 1."""
    chars = list(s)
    for i in range(len(chars) - 1, -1, -1):
        idx = BASE36.index(chars[i])
        if idx < 35:
            chars[i] = BASE36[idx + 1]
            break
        else:
            chars[i] = "0"
    else:
        # All characters rolled over; prepend '1' (e.g., ZZZZ -> 10000)
        chars.insert(0, "1")
    return "".join(chars)


def main():
    ids_file = "ids.txt"
    if not os.path.exists(ids_file):
        print("ORD-0000")
        return

    with open(ids_file) as f:
        lines = [line.strip() for line in f if line.strip()]

    if not lines:
        print("ORD-0000")
        return

    last_id = lines[-1]
    prefix = "ORD-"
    if last_id.startswith(prefix):
        suffix = last_id[len(prefix):]
    else:
        suffix = last_id

    next_suffix = increment(suffix)
    print(f"{prefix}{next_suffix}")


if __name__ == "__main__":
    main()

