#!/usr/bin/env python3
"""Read events.jsonl, remove duplicate event_ids (keep first), write deduped.jsonl."""

import json

def main():
    seen = set()
    with open("events.jsonl", encoding="utf-8") as fin, \
         open("deduped.jsonl", "w", encoding="utf-8") as fout:
        for line in fin:
            line = line.strip()
            if not line:
                continue
            event = json.loads(line)
            eid = event.get("event_id")
            if eid is None or eid in seen:
                continue
            seen.add(eid)
            fout.write(line + "\n")

if __name__ == "__main__":
    main()

