import glob
import os

def main():
    measurements = []
    for path in glob.glob(os.path.join('inbox', '*.txt')):
        with open(path) as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue
                # Each line holds one integer measurement (may be tab-separated from a line number)
                tokens = line.split()
                if tokens:
                    try:
                        measurements.append(int(tokens[-1]))
                    except ValueError:
                        pass  # skip malformed lines

    n = len(measurements)
    total = sum(measurements)
    avg = total / n if n > 0 else 0.0

    with open('report.txt', 'w') as f:
        f.write(f'entries {n}\n')
        f.write(f'total {total}\n')
        f.write(f'average {avg:.2f}\n')

if __name__ == '__main__':
    main()

