#!/usr/bin/env python3
"""Generate manifest.json with SHA-256 digests for every file under release/."""

import hashlib
import json
from pathlib import Path

RELEASE_DIR = Path("release")
MANIFEST_PATH = Path("manifest.json")


def sha256_digest(path: Path) -> str:
    """Return the SHA-256 hex digest of the file at *path*."""
    return hashlib.sha256(path.read_bytes()).hexdigest()


def main() -> None:
    manifest = {}
    # Walk release/ collecting all regular files.
    for path in sorted(RELEASE_DIR.rglob("*")):
        if path.is_file():
            # Store the path relative to the repository root, using forward slashes.
            rel = str(path.as_posix())
            manifest[rel] = sha256_digest(path)

    MANIFEST_PATH.write_text(json.dumps(manifest, indent=2) + "\n")
    print(f"Wrote {MANIFEST_PATH} ({len(manifest)} entries)")


if __name__ == "__main__":
    main()

