"""Count word frequencies in all .txt files under docs/."""

import os
import re
from collections import Counter


def words_from_file(filepath):
    """Yield lowercased words stripped of punctuation . , ; : ! ? at edges."""
    with open(filepath, encoding="utf-8") as f:
        for line in f:
            for raw in line.split():
                word = raw.lower().strip(".,;:!?")
                if word:
                    yield word


def main():
    cwd = os.getcwd()
    docs_dir = os.path.join(cwd, "docs")
    counter = Counter()

    for root, _dirs, files in os.walk(docs_dir):
        for fn in files:
            if fn.endswith(".txt"):
                path = os.path.join(root, fn)
                counter.update(words_from_file(path))

    out_path = os.path.join(cwd, "counts.txt")
    with open(out_path, "w", encoding="utf-8") as out:
        for word in sorted(counter):
            out.write(f"{word} {counter[word]}\n")


if __name__ == "__main__":
    main()

