#!/usr/bin/env python3
"""Rotate old entries from app.log into archive.log."""

import sys
from datetime import datetime, timezone

ARCHIVE_FILE = "archive.log"
LOG_FILE = "app.log"

CUTOFF_DAYS = 7
SECONDS_PER_DAY = 86400


def parse_timestamp(line: str) -> datetime | None:
    """Try to parse 'YYYY-MM-DD HH:MM:SS' from the start of a line."""
    try:
        return datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S").replace(
            tzinfo=timezone.utc
        )
    except (ValueError, IndexError):
        return None


def main() -> None:
    if len(sys.argv) != 2:
        print(f"Usage: {sys.argv[0]} AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
        as_of = int(sys.argv[1])
    except ValueError:
        print("AS_OF must be an integer Unix timestamp.", file=sys.stderr)
        sys.exit(1)

    cutoff_ts = as_of - CUTOFF_DAYS * SECONDS_PER_DAY
    cutoff_dt = datetime.fromtimestamp(cutoff_ts, tz=timezone.utc)

    try:
        with open(LOG_FILE, "r") as f:
            lines = f.readlines()
    except FileNotFoundError:
        print(f"{LOG_FILE} not found, nothing to do.", file=sys.stderr)
        return

    keep = []
    archive = []

    for line in lines:
        if not line.strip():
            continue
        ts = parse_timestamp(line)
        if ts is None:
            # Lines without a valid timestamp stay in app.log
            keep.append(line)
        elif ts < cutoff_dt:
            archive.append(line)
        else:
            keep.append(line)

    # Rewrite app.log with entries that are kept
    with open(LOG_FILE, "w") as f:
        f.writelines(keep)

    # Append rotated entries to archive.log
    if archive:
        with open(ARCHIVE_FILE, "a") as f:
            f.writelines(archive)


if __name__ == "__main__":
    main()

