            new_entries.append(line)
            continue
        dt = parse_line_ts(line)
        if dt is None:
            # Unparseable line – keep in app.log
            new_entries.append(line)
        elif dt.timestamp() < cutoff:
            old_entries.append(line)
        else:
            new_entries.append(line)

    # Append old entries to archive.log
    if old_entries:
        with open("archive.log", "a") as f:
            for entry in old_entries:
                f.write(entry + "\n")

    # Rewrite app.log with remaining entries
    with open("app.log", "w") as f:
        for entry in new_entries:
            if entry:  # non-empty lines get a newline
                f.write(entry + "\n")
        # If last line was empty, don't add extra trailing newline
        # Actually, let's just write them all consistently

